const nestedWorkspaceSlug = `-- name: NestedWorkspaceSlug :one

SELECT id, slug FROM workspaces
WHERE org_id = $1 AND state <> 'Deleted'
  AND (slug = $2 OR slug LIKE $2 || '-%' OR $2 LIKE slug || '-%')
ORDER BY id
LIMIT 1
`

type NestedWorkspaceSlugParams struct {
	OrgID string
	Slug  string
}

type NestedWorkspaceSlugRow struct {
	ID   string
	Slug string
}

// Workspaces (PRODUCT-PLAN §4.4, §17; architecture/02-data-model §4).
// A Workspace of the organization, not Deleted, whose slug equals this one
// or nests with it at a '-' (solar and solar-prod): Capsule's
// forceTenantPrefix would let one create Namespaces in the other's names.
// Slugs hold only [a-z0-9-], so LIKE needs no escaping.
func (q *Queries) NestedWorkspaceSlug(ctx context.Context, arg NestedWorkspaceSlugParams) (NestedWorkspaceSlugRow, error) {
	row := q.db.QueryRow(ctx, nestedWorkspaceSlug, arg.OrgID, arg.Slug)
	var i NestedWorkspaceSlugRow
	err := row.Scan(&i.ID, &i.Slug)
	return i, err
}

const resyncGroupMembers = `-- name: ResyncGroupMembers :execrows
UPDATE group_members
SET sync_status = 'Pending', sync_attempts = 0, next_sync_at = now(), last_error = '', updated_at = now()
WHERE group_id = ANY($1::text[]) AND deleted_at IS NULL
`

// The set of bindings changed, so whether each live member of these groups
// belongs in tenantry:tenant-users may have changed: the group sync worker
// works it out again (IMPLEMENTATION-PLAN §5.2).
func (q *Queries) ResyncGroupMembers(ctx context.Context, groupIds []string) (int64, error) {
	result, err := q.db.Exec(ctx, resyncGroupMembers, groupIds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

