func (q *Queries) UserHasWorkspaceBinding(ctx context.Context, userID string) (bool, error) {
	row := q.db.QueryRow(ctx, userHasWorkspaceBinding, userID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

